public static Character toCharacterObject(final char ch) {
    // check if the character is a ASCII 7-bit character
    if (ch <= 127) {
        // use the cache to retrieve the Character object for the character
        Character[] cache = Character.valueOfCache;
        if (cache != null) {
            int low = 0;
            int high = cache.length - 1;
            while (high >= low) {
                int mid = (low + high) >>> 1;
                char midValue = cache[mid].charValue();
                if (midValue < ch) {
                    low = mid + 1;
                } else if (midValue > ch) {
                    high = mid - 1;
                } else {
                    return cache[mid];
                }
            }
            cache[low] = Character.valueOf(ch);
            return cache[low];
        }
    }
    return Character.valueOf(ch);
}

