public static String[] toNoNullStringArray(Object[] array) {
    // Check if the input array is null or empty
    if (array == null || array.length == 0) {
        return new String[0];
    }

    // Create a new array without null elements
    String[] result = new String[array.length];
    int idx = 0;
    for (Object obj : array) {
        if (obj != null && obj instanceof String) {
            result[idx++] = (String) obj;
        }
    }

    // Trim the result array to remove any trailing null elements
    if (idx < result.length) {
        String[] trimmed = new String[idx];
        System.arraycopy(result, 0, trimmed, 0, idx);
        result = trimmed;
    }

    return result;
}

