public int parseEndOfLine(String headerPart, int end) {
    // find the next \r\n sequence
    int nextCr = headerPart.indexOf('\r', end);
    int nextLf = headerPart.indexOf('\n', end);
    int nextEndOfLine = (nextCr != -1) ? nextCr : nextLf;

    // if no \r\n sequence found, return -1
    if (nextEndOfLine == -1) {
        return -1;
    }

    // check if we have a CR LF sequence
    if (nextEndOfLine > 0 && headerPart.charAt(nextEndOfLine - 1) == '\r') {
        // skip the CR
        nextEndOfLine--;
    }

    return nextEndOfLine;
}

