TreeNode<T> rotateRight(TreeNode<T> node) {
    TreeNode<T> parent = node.getParent();
    if(parent == null) { // base case: node is the root
        return null;
    }

    // case 1: node is the left child of its parent
    if(parent.getLeft() == node) {
        parent.setLeft(node.getRight());
    }
    // case 2: node is the right child of its parent
    else if(parent.getRight() == node) {
        parent.setRight(node.getLeft());
    }
    // case 3: node is neither the left nor right child of its parent
    else {
        throw new IllegalStateException("Node is not a child of its parent");
    }

    node.setParent(parent.getParent());
    if(node.getParent() != null) {
        node.getParent().setLeft(node);
    }

    parent.setRight(node);
    node.setLeft(parent);

    return node;
}

