  // Check if $n$ is a power of 2
  if (n > 1 && (n & (n - 1)) == 0) {
    // If $n$ is a power of 2, return $log_2 (n)$
    return 32 - Integer.numberOfLeadingZeros(n);
  } else {
    // If $n$ is not a power of 2, return $log_2 (n)$ + 1
    return 33 - Integer.numberOfLeadingZeros(n - 1);
  }
}

