private Edge edgeToNext() {
    if (this.isRealNode()) {
        // If this node is real, then the edge to the next node is simply the edge that connects the previous node to this node
        return this.graph.getEdge(this.graph.getNode(this.id - 1), this);
    } else {
        // If this node is virtual, then we need to find the real node that this node maps to and then return the edge connecting the previous node to the corresponding real node
        // Note that this.id - 1 is the index of the real node that this node maps to in the graph
        Node realNode = this.graph.getNode(this.id - 1);
        return this.graph.getEdge(this.graph.getNode(this.id - 2), realNode);
    }
}

