    // Check if the given vertices form a subgraph that is complete
    if (graph.containsVertex(vertices)) {
        Set<E> edges = graph.edgesOf(vertices);
        for (E edge : edges) {
            if (!vertices.containsAll(graph.getEdgeTargets(edge))) {
                return false;
            }
        }
        return true;
    }
    return false;
}

