        return result;
    }

    // Find the first character that is not a delimitor
    int start = u.getPath().indexOf(0);
    // if the first character is a delimitor, move to the next character
    if (u.getPath().charAt(start) == '/') {
        start++;
    }

    // Find the index of the last character that is not a delimitor
    int end = u.getPath().length() - 1;
    // if the last character is a delimitor, move to the previous character
    if (u.getPath().charAt(end) == '/') {
        end--;
    }

    // Extract the path segments
    String[] segments = u.getPath().substring(start, end + 1).split("/");
    // If the first segment is empty, discard it
    if (segments[0].isEmpty()) {
        ListIterator<String> iterator = Arrays.asList(segments).listIterator(1);
        while (iterator.hasNext()) {
