    // Check if the request has a session
    HttpSession session = r.getSession(false);
    if (session != null) {
        // Get the user ID from the session
        String userId = (String) session.getAttribute("userId");
        if (userId != null) {
            // Check if there is any meteor data for the user
            Meteor meteor = (Meteor) session.getAttribute("meteor");
            if (meteor != null) {
                // Return the meteor if it exists
                return meteor;
            }
            // Otherwise, create a new meteor
            return new Meteor(userId);
        }
    }
    // If the request doesn't have a session or the user ID is missing, return null
    return null;
}

