public static String trimTrailingWhitespace(String str) {
    if (str == null) {
        return null;
    }

    int strLen = str.length();
    if (strLen == 0) {
        return str;
    }

    int start = strLen;
    for (int i = strLen - 1; i >= 0; i--) {
        if (!Character.isWhitespace(str.charAt(i))) {
            start = i + 1;
            break;
        }
    }
    return str.substring(0, start);
}

