        return null;
    }

    int lastDotIndex = path.lastIndexOf('.');
    if (lastDotIndex == -1) {
        return path;
    }

    int lastSeparatorIndex = path.lastIndexOf(File.separatorChar);
    if (lastSeparatorIndex == -1) {
        return path.substring(0, lastDotIndex);
    }

    if (lastSeparatorIndex > lastDotIndex) {
        return path;
    }

    return path.substring(0, lastDotIndex);
}

