public static String applyRelativePath(String path, String relativePath) {
    // Split the path into its components
    String[] pathComponents = path.split("/");
    String[] relativePathComponents = relativePath.split("/");

    // Create a new array that is the same size as the path components
    String[] newPathComponents = new String[pathComponents.length];

    // Copy the path components into the new array
    System.arraycopy(pathComponents, 0, newPathComponents, 0, pathComponents.length);

    // Iterate over the relative path components
    for (int i = 0; i < relativePathComponents.length; i++) {
        // If the current relative path component is "..", remove the previous path component
        if (relativePathComponents[i].equals("..")) {
            newPathComponents[i - 1] = null;
        }
        // Otherwise, add the current relative path component to the new path
        else {
            newPathComponents[i] = relativePathComponents[i];
        }
    }

    // Join the new path components into a single string
    StringBuilder newPath = new StringBuilder();
    for (String component : newPathComponents) {
        if (component != null) {
            newPath.append("/").append(component);
        }
    }

    // Return the new path
    return newPath.toString();
}

