    List<String> newPathParts = new ArrayList<>();

    // Iterate over the relative path parts
    for (String relativePathPart : relativePathParts) {
        // If the part is "..", remove the last path part
        if (relativePathPart.equals("..")) {
            if (!newPathParts.isEmpty()) {
                newPathParts.remove(newPathParts.size() - 1);
            }
        } else if (relativePathPart.equals(".")) {
            // If the part is ".", do nothing
        } else {
            // If the part is not ".." or ".", add it to the new path parts
            newPathParts.add(relativePathPart);
        }
    }

    // Join the new path parts into a single string
    String newPath = String.join("/", newPathParts);

    // If the new path is empty, return the initial path
    if (newPath.isEmpty()) {
        return path;
    }

    // Otherwise, return the new path
    return newPath;
}

