public String format(final LoggingEvent event) {
    String result = "";

    // Get the logging level
    String level = event.getLevel().toString();

    // Get the message
    String message = event.getMessage();

    // Format the message according to the level
    if (level.equals("DEBUG")) {
        result = String.format("[DEBUG] %s", message);
    } else if (level.equals("INFO")) {
        result = String.format("[INFO] %s", message);
    } else if (level.equals("WARN")) {
        result = String.format("[WARN] %s", message);
    } else if (level.equals("ERROR")) {
        result = String.format("[ERROR] %s", message);
    } else if (level.equals("FATAL")) {
        result = String.format("[FATAL] %s", message);
    }

    // Add the event timestamp
    result += event.getTimeStamp();

    // Return the formatted string
    return result;
}

