private void send(final String message) {
    // Find the clients that are currently connected
    final List<Client> clients = getClients();

    // Loop through the clients and send them the message
    for (Client client : clients) {
        // Create a new TelnetWriter for this client
        TelnetWriter writer = new TelnetWriter(client);

        // Write the message to the client
        writer.write(message);

        // Flush the writer
        writer.flush();
    }
