public void abbreviate(final int nameStart, final StringBuffer buf) {
    String initials = "";
    String name = "";
    String delimiter = " ";
    int lastSpace = -1;
    int curIndex = nameStart;

    while (curIndex < buf.length()) {
        char ch = buf.charAt(curIndex);
        if (ch == '.') {
            delimiter = ch;
        }
        if (ch != delimiter) {
            buf.deleteCharAt(curIndex);
        } else if (lastSpace == -1) {
            lastSpace = curIndex;
        }
        if (lastSpace != -1 && curIndex > lastSpace + 1) {
            initials = buf.substring(curIndex + 1, lastSpace + 1);
        }
        curIndex++;
    }

    name = initials.replaceAll("\\.", "");

    if (name.isEmpty()) {
        buf.setCharAt(nameStart, '?');
    } else {
        buf.replace(nameStart, nameStart + 1, name);
    }
}

