public Mappings diffStructure(String tableName, Mappings mappings) {
    // Create a copy of input mappings to avoid modifying the original object
    Mappings diffMappings = new Mappings(mappings);

    // Get the index mapping from diffMappings
    IndexMappings indexMappings = diffMappings.getIndexMappings(tableName);

    // Get the index mapping from input mappings
    IndexMappings inputMappings = mappings.getIndexMappings(tableName);

    // Iterate over the fields in the input mappings
    for (String fieldName : inputMappings.getFields().keySet()) {
        // Check if the field exists in the diffMappings
        if (diffMappings.getFields().containsKey(fieldName)) {
            // Get the field mapping from the diffMappings
            FieldMapping fieldMapping = diffMappings.getFields().get(fieldName);

            // Check if the field type is not set in the diffMappings
            if (fieldMapping.getType() == null) {
                // Set the field type to the one in the input mappings
                fieldMapping.setType(inputMappings.getField(fieldName).getType());
            }
        } else {
            // Add the field to the diffMappings
            diffMappings.getFields().put(fieldName, inputMappings.getField(fieldName));
        }
    }

    // Return the diffMappings
    return diffMappings;
}

