    Mappings differenceMappings = new Mappings();

    // Get the fields that exist in the input mappings but not in the current mappings
    Set<String> existingFields = mappings.getFields(tableName);
    Set<String> currentFields = getFields(tableName);
    Set<String> missingFields = Sets.difference(existingFields, currentFields);

    // Add the missing fields to the difference mappings
    for (String field : missingFields) {
        differenceMappings.put(tableName, field, Mapping.builder().autoGenerate().build());
    }

    return differenceMappings;
}

