public static long compressTimeBucket(long timeBucket, int dayStep) {
        // Calculate the day portion of the time bucket
        int dayPortion = (int) (timeBucket % 100000000L);

        // Calculate the month portion of the time bucket
        int monthPortion = (int) ((timeBucket / 100000000L) % 100L);

        // Calculate the year portion of the time bucket
        int yearPortion = (int) ((timeBucket / 100000000000L) % 10000L);

        // Compress the time bucket
        long compressedTimeBucket = yearPortion * 100000000000L + monthPortion * 100000000L + dayPortion;

        // Add the day step to the compressed time bucket
        compressedTimeBucket += dayStep;

        // Return the compressed time bucket
        return compressedTimeBucket;
    }

