public static List<ThreadSnapshot> parseFromFileWithTimeRange(File file,List<ProfileAnalyzeTimeRange> timeRanges) throws IOException {
    // create an empty list to store thread snapshots
    List<ThreadSnapshot> threadSnapshots = new ArrayList<>();
    // open the file as a random access file
    RandomAccessFile raf = new RandomAccessFile(file, "r");
    // seek to the beginning of the file
    raf.seek(0);
    // read the file's header
    raf.readLine();
    // loop through each time range
    for (ProfileAnalyzeTimeRange timeRange : timeRanges) {
        // get the start and end times
        long startTime = timeRange.getStartTime();
        long endTime = timeRange.getEndTime();
        // create a new thread snapshot
        ThreadSnapshot threadSnapshot = new ThreadSnapshot();
        threadSnapshot.setFileName(file.getName());
        threadSnapshot.setStartTime(startTime);
        threadSnapshot.setEndTime(endTime);
        // loop through each line in the file
        String line;
        while ((line = raf.readLine()) != null) {
            // check if the line contains the start time
            if (line.contains(String.valueOf(startTime))) {
                // create a new profile
                Profile profile = new Profile();
                // read the profile's name and value
                String[] fields = line.split("\\s+");
                profile.setName(fields[1]);
                profile.setValue(Double.parseDouble(fields[2]));
                // add the profile to the thread snapshot
                threadSnapshot.addProfile(profile);
            }
            // check if the line contains the end time
            if (line.contains(String.valueOf(endTime))) {
                // break out of the loop if the end time is reached
                break;
            }
        }
        // add the thread snapshot to the list
        threadSnapshots.add(threadSnapshot);
    }
    // close the random access file
    raf.close();
    // return the list of thread snapshots
    return threadSnapshots;
}

