public static LinkedBuffer writeUTF8(CharSequence str, WriteSession session, LinkedBuffer lb) {

    // Check if the string is null or empty
    if (str == null || str.length() == 0) {
        // If the string is null or empty, do nothing
        return lb;
    }

    // Get the number of characters in the string
    int len = str.length();

    // Get the buffered used for writing
    byte[] buffer = lb.getByteBuffer();

    // The index of the first character to be written
    int startIdx = lb.getWriteIndex();

    // The number of bytes written so far
    int totalWritten = 0;

    // The index of the current character to be written
    int i = 0;

    // While there are still characters to be written
    while (i < len) {
        // Get the code point of the current character
        int codePoint = str.codePointAt(i);

        // If the code point is a ASCII character
        if (codePoint <= 0x7F) {
            // Write the character to the buffer
            buffer[startIdx + totalWritten] = (byte) codePoint;
            // Increment the number of bytes written
            totalWritten++;
        } else {
            // If the code point is a non-ASCII character, write it as a multi-byte sequence
            int offset = (int) Math.floor(codePoint / 0x100) % 0x80 - 0x80;
            buffer[startIdx + totalWritten] = (byte) (0xC0 | offset);
            buffer[startIdx + totalWritten + 1] = (byte) (0x80 | (codePoint & 0x3F));
            totalWritten += 2;
        }

        // Increment the index of the current character to be written
        i++;
    }

    // Set the write index to the end of the written bytes
    lb.setWriteIndex(startIdx + totalWritten);

    return lb;
}

